ValidationRule.errorConditionFormula:
AND( RecordType.DeveloperName = 'Sales_Offers_Request', NOT ( $UserRole.Id = $Label.QF_Support_QIC_Member), /*QF-Support-Agency Support-QAC*/ ISPICKVAL ( Type , "Bespoke Incentive"), NOT ( CONTAINS ( $User.Level__c , "SO(SME)")),
OR ( ISBLANK( Objective__c ), ISBLANK( Key_Messages__c ), ISBLANK( What_does_the_Customer_hope_to_achieve__c ), ISPICKVAL ( Initial_Customer_conversation_completed__c ,""), ISPICKVAL ( Included_in_your_Strategic_Account_Plan__c , "") )
)
